export const SNAKE_HTML =
  "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\">\n<title>Snake</title>\n<!--\n  Ally course component: GAME / SNAKE.\n\n  Gameplay is a port of Jack Rugile's \"Snakely\" pen\n  (https://codepen.io/jackrugile/pen/bGRWbK) — a CSS/DOM-rendered snake with no\n  canvas, which is why it fits this family of bundles at all. The rules (grow by\n  one per food, speed up as you grow, wrap at the walls instead of dying on\n  them) are kept faithfully; everything the learner sees is redrawn in Ally UI.\n\n  This page is loaded in a sandboxed iframe by GameItemPlayer (web) and in a\n  WebView by GamePlayer (mobile). It talks to its host only through the three\n  postMessage events documented in the bridge at the bottom of this file — the\n  same contract every other game bundle speaks.\n\n  Departures from the original, all deliberate:\n\n  - No arrow-hint overlay pointing at the food. It reads as a hint system on a\n    component whose whole job is to be a thirty-second breather, not a puzzle\n    to be coached through.\n  - The board is a fixed logical grid sized to whatever frame the host gives\n    it, not a viewport-filling stage — this runs inside a course item, not\n    full-screen.\n  - Speed still ramps with length (an interactive-learning-events principle:\n    challenge should track skill so the player stays in flow instead of\n    getting bored or dropping out), but it floors rather than climbing forever\n    — an escalation with no ceiling eventually beats anyone, which is the\n    opposite of a low-friction breather.\n  - The wraparound walls stay: dying only to your own tail, never to an edge,\n    is what keeps this the gentle game in the set rather than the punishing\n    one, and it is the original's defining trick.\n  - A death auto-restarts a beat later with no modal or confirm(), same as the\n    tic-tac-toe bundle — ceremony nobody asked for on a game that exists to\n    cost nothing to replay. A manual restart button covers a learner who wants\n    out of a boring run early.\n  - Touch swipes drive direction alongside arrow keys / WASD, since a WebView\n    has no keyboard.\n\n  The font stack asks for IBM Plex Serif and expects not to get it: this page\n  is served from public/ with no @font-face of its own and is inlined offline\n  on mobile, so it lands on a serif fallback that still reads as Ally UI.\n  Colours are the daylight theme's literal values (index.css) — an iframe\n  cannot see the app's CSS variables.\n-->\n<style>\n  :root {\n    /* Ally daylight palette (src/index.css) — literals, since the iframe has\n       no access to the app's --color-* variables. */\n    --primary-50: #ebf0fa;\n    --primary-100: #d7e2f4;\n    --primary-400: #4a7dcf;\n    --primary-500: #264d8e;\n    --primary-600: #1f3f75;\n    --success-50: #e8f5e9;\n    --success-200: #a5d6a7;\n    --success-700: #388e3c;\n    --background: #ffffff;\n    --background-secondary: #f4f4f4;\n    --border-light: #e0e0e0;\n    --border-medium: #c6c6c6;\n    --typography-500: rgba(0, 0, 0, 0.32);\n    --typography-700: rgba(0, 0, 0, 0.54);\n    --typography-900: rgba(0, 0, 0, 0.87);\n    --font: \"IBM Plex Serif\", Georgia, \"Times New Roman\", serif;\n  }\n\n  * { box-sizing: border-box; }\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    height: 100%;\n  }\n\n  body {\n    background: var(--background);\n    color: var(--typography-900);\n    font-family: var(--font);\n    font-size: 14px;\n    line-height: 24px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n    -webkit-user-select: none;\n    user-select: none;\n    -webkit-tap-highlight-color: transparent;\n  }\n\n  .wrap {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    padding: 12px;\n    width: 100%;\n    height: 100%;\n    max-width: 380px;\n  }\n\n  /* Every row but the board refuses to shrink. Without this, a frame one\n     pixel too short makes flexbox squash whichever row can give — and since\n     sizeBoard() measures those rows to decide how much is left for the board,\n     a squashed row feeds it a smaller chrome, which grows the board, which\n     squashes the row further. Same trap documented in the tic-tac-toe bundle. */\n  .panel,\n  #status,\n  .board {\n    flex: 0 0 auto;\n  }\n\n  /* ---- Score panel ---- */\n\n  .panel {\n    display: flex;\n    align-items: center;\n    gap: 18px;\n    width: 100%;\n  }\n\n  .stat { text-align: left; }\n\n  .stat dt {\n    margin: 0;\n    font-size: 11px;\n    line-height: 16px;\n    letter-spacing: 0.02em;\n    text-transform: uppercase;\n    color: var(--typography-500);\n  }\n\n  .stat dd {\n    margin: 0;\n    font-size: 20px;\n    line-height: 26px;\n    font-weight: 600;\n    color: var(--typography-900);\n  }\n\n  .panel-spacer { flex: 1 1 auto; }\n\n  .icon-button {\n    appearance: none;\n    border: 1px solid var(--border-light);\n    background: var(--background);\n    color: var(--typography-700);\n    border-radius: 8px;\n    width: 32px;\n    height: 32px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    padding: 0;\n    cursor: pointer;\n    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;\n  }\n\n  .icon-button:hover {\n    background: var(--primary-50);\n    border-color: var(--primary-100);\n    color: var(--primary-500);\n  }\n\n  .icon-button:focus-visible {\n    outline: 2px solid var(--primary-500);\n    outline-offset: 1px;\n  }\n\n  .icon-button svg { width: 16px; height: 16px; display: block; }\n\n  /* ---- Status line ---- */\n\n  #status {\n    margin: 0;\n    min-height: 18px;\n    font-size: 13px;\n    line-height: 18px;\n    color: var(--typography-700);\n    text-align: center;\n  }\n\n  #status.is-result {\n    color: var(--typography-900);\n    font-weight: 600;\n  }\n\n  /* ---- Board ----\n\n     Square, and sized in JS from the space actually left over — see\n     sizeBoard(). `flex: 0 0 auto` matters for the same reason the tic-tac-toe\n     board pins it: a shrinkable board in too short a frame keeps its cell\n     size and loses its bottom rows behind `overflow: hidden` instead of\n     visibly overflowing, which is the failure that is easy to notice. */\n  .board {\n    position: relative;\n    border: 1px solid var(--border-light);\n    border-radius: 10px;\n    overflow: hidden;\n    background-color: var(--background);\n  }\n\n  .segment {\n    position: absolute;\n    border-radius: 3px;\n    background: var(--primary-400);\n  }\n\n  .segment.head {\n    background: var(--primary-500);\n    box-shadow: 0 0 6px rgba(38, 77, 142, 0.55);\n    z-index: 2;\n  }\n\n  .segment.food {\n    background: var(--success-700);\n    box-shadow: 0 0 6px rgba(56, 142, 60, 0.5);\n    animation: pulse 1.1s ease-in-out infinite;\n    transform-origin: center;\n  }\n\n  @keyframes pulse {\n    0%, 100% { transform: scale(0.82); opacity: 0.88; }\n    50% { transform: scale(1.05); opacity: 1; }\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .segment.food { animation: none; }\n  }\n\n  /* In a short frame the board has already shrunk itself; pull the chrome in\n     to match. */\n  @media (max-height: 380px) {\n    .wrap { gap: 6px; }\n    .stat dd { font-size: 17px; }\n  }\n</style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <div class=\"panel\">\n      <dl class=\"stat\"><dt id=\"score-label\">Score</dt><dd id=\"score\">0</dd></dl>\n      <dl class=\"stat\"><dt id=\"best-label\">Best</dt><dd id=\"best\">0</dd></dl>\n      <div class=\"panel-spacer\"></div>\n      <button type=\"button\" class=\"icon-button\" id=\"restart\"></button>\n    </div>\n\n    <!-- Announced to screen readers as it changes: this is the only place a\n         run's result is stated. -->\n    <p id=\"status\" role=\"status\" aria-live=\"polite\"></p>\n\n    <div class=\"board\" id=\"board\" role=\"img\" aria-label=\"Snake board\"></div>\n  </div>\n\n<script>\n(function () {\n  'use strict';\n\n  /* =====================================================================\n     Host bridge — identical contract to every other bundle in this family.\n\n       game -> host  { source:'ally-game', game, type:'ready' }\n       game -> host  { source:'ally-game', game, type:'started' }\n       game -> host  { source:'ally-game', game, type:'over', score, highScore }\n\n       host -> game  { source:'ally-game-host', type:'focus' }\n\n     One file, two hosts: an <iframe> in the web app (post to window.parent)\n     and a react-native-webview on mobile (post a JSON string to\n     window.ReactNativeWebView). Scores are a personal best and nothing more —\n     a game in a course never gates, unlocks or grades anything.\n     ===================================================================== */\n\n  var GAME = 'SNAKE';\n  var iframeHost = window.parent !== window ? window.parent : null;\n\n  function post(type, extra) {\n    var message = { source: 'ally-game', game: GAME, type: type };\n    for (var key in extra) {\n      if (Object.prototype.hasOwnProperty.call(extra, key)) message[key] = extra[key];\n    }\n    if (window.ReactNativeWebView) {\n      window.ReactNativeWebView.postMessage(JSON.stringify(message));\n      return;\n    }\n    // '*' because a sandboxed iframe has an opaque origin that matches no\n    // concrete target, and the payload carries nothing worth protecting.\n    if (iframeHost) iframeHost.postMessage(message, '*');\n  }\n\n  var announcedStart = false;\n  function markStarted() {\n    if (announcedStart) return;\n    announcedStart = true;\n    post('started');\n  }\n\n  window.addEventListener('message', function (event) {\n    var data = event.data;\n    if (!data || data.source !== 'ally-game-host') return;\n    if (data.strings) {\n      applyStrings(data.strings);\n      renderLabels();\n    }\n    if (data.type === 'focus') window.focus();\n  });\n\n  /* =====================================================================\n     Copy\n\n     Baked in English and overridden by the host, which is the side that\n     knows the learner's language: the web app sends these with its `focus`\n     message, the mobile app sets `window.__allyGameStrings` before this\n     document loads. English is the fallback either way, so a host that\n     sends nothing still gets a working game.\n     ===================================================================== */\n\n  var STRINGS = {\n    score: 'Score',\n    best: 'Best',\n    restart: 'Start over',\n    gameOver: 'Game over — {{score}}'\n  };\n\n  if (window.__allyGameStrings) applyStrings(window.__allyGameStrings);\n\n  function applyStrings(next) {\n    for (var key in STRINGS) {\n      if (Object.prototype.hasOwnProperty.call(next, key) &&\n          typeof next[key] === 'string') {\n        STRINGS[key] = next[key];\n      }\n    }\n  }\n\n  function fill(template, values) {\n    return template.replace(/{{(\\w+)}}/g, function (whole, name) {\n      return Object.prototype.hasOwnProperty.call(values, name)\n        ? String(values[name])\n        : whole;\n    });\n  }\n\n  /* =====================================================================\n     Board + rules\n\n     A fixed logical grid (COLS x ROWS), independent of the pixel size the\n     frame actually gets — sizeBoard() maps grid cells to pixels each time the\n     frame resizes. The wall wraps: the only way to end a run is running into\n     your own tail.\n     ===================================================================== */\n\n  var COLS = 14;\n  var ROWS = 14;\n  var START_LENGTH = 4;\n  var START_INTERVAL_MS = 140;\n  var MIN_INTERVAL_MS = 60;\n  var SPEEDUP_PER_FOOD_MS = 4; // ramps difficulty with skill, then floors —\n                                // an unbounded ramp eventually beats anyone.\n  var RESTART_DELAY_MS = 1200;\n  var SWIPE_MIN_PX = 20;\n\n  var boardEl = document.getElementById('board');\n  var scoreLabelEl = document.getElementById('score-label');\n  var scoreEl = document.getElementById('score');\n  var bestLabelEl = document.getElementById('best-label');\n  var bestEl = document.getElementById('best');\n  var statusEl = document.getElementById('status');\n  var restartEl = document.getElementById('restart');\n\n  function renderLabels() {\n    scoreLabelEl.textContent = STRINGS.score;\n    bestLabelEl.textContent = STRINGS.best;\n    restartEl.setAttribute('aria-label', STRINGS.restart);\n    restartEl.setAttribute('title', STRINGS.restart);\n  }\n\n  var cellSize = 0;\n  var segments = [];      // [{col,row}, ...] index 0 is the head\n  var segmentEls = [];\n  var food = null;        // {col,row}\n  var foodEl = null;\n  var heading = 'right';  // last committed movement\n  var queuedDir = 'right'; // last accepted input, guarded against reversal\n  var score = 0;\n  var best = 0;\n  var tickIntervalMs = START_INTERVAL_MS;\n  var running = true;\n  var resetTimer = null;\n  var tickAccumMs = 0;\n  var lastFrameTime = null;\n\n  function randomInt(maxExclusive) {\n    return Math.floor(Math.random() * maxExclusive);\n  }\n\n  function occupied(col, row, cells) {\n    for (var i = 0; i < cells.length; i++) {\n      if (cells[i].col === col && cells[i].row === row) return true;\n    }\n    return false;\n  }\n\n  function placeFood() {\n    var col, row;\n    do {\n      col = randomInt(COLS);\n      row = randomInt(ROWS);\n    } while (occupied(col, row, segments));\n    food = { col: col, row: row };\n  }\n\n  function resetGame() {\n    var startRow = Math.floor(ROWS / 2);\n    var startCol = Math.floor(COLS / 2);\n    segments = [];\n    for (var i = 0; i < START_LENGTH; i++) {\n      segments.push({ col: startCol - i, row: startRow });\n    }\n    heading = 'right';\n    queuedDir = 'right';\n    score = 0;\n    tickIntervalMs = START_INTERVAL_MS;\n    tickAccumMs = 0;\n    announcedStart = false;\n    scoreEl.textContent = '0';\n    setStatus('', false);\n    placeFood();\n  }\n\n  /** Same double-guard the tic-tac-toe bundle uses for its own input: a new\n   * direction is only accepted if it conflicts with neither the last\n   * *requested* direction nor the last *committed* one. Without the second\n   * check, two key presses landing inside the same tick could queue a\n   * reversal that runs the head straight into the neck it just left. */\n  var OPPOSITE = { up: 'down', down: 'up', left: 'right', right: 'left' };\n  function requestDirection(next) {\n    if (OPPOSITE[next] === queuedDir || OPPOSITE[next] === heading) return;\n    queuedDir = next;\n    markStarted();\n  }\n\n  function step() {\n    var head = segments[0];\n    var next = { col: head.col, row: head.row };\n    if (queuedDir === 'up') next.row -= 1;\n    else if (queuedDir === 'down') next.row += 1;\n    else if (queuedDir === 'left') next.col -= 1;\n    else next.col += 1;\n\n    // Wrap at the walls instead of dying on them.\n    if (next.col < 0) next.col = COLS - 1;\n    if (next.col >= COLS) next.col = 0;\n    if (next.row < 0) next.row = ROWS - 1;\n    if (next.row >= ROWS) next.row = 0;\n\n    var ateFood = food && next.col === food.col && next.row === food.row;\n    // The tail cell is safe to enter unless this move also grows the snake\n    // into it (eating on the same tick the tail would have vacated it).\n    var bodyToCheck = ateFood ? segments : segments.slice(0, segments.length - 1);\n    if (occupied(next.col, next.row, bodyToCheck)) {\n      onGameOver();\n      return;\n    }\n\n    segments.unshift(next);\n    heading = queuedDir;\n\n    if (ateFood) {\n      score += 1;\n      scoreEl.textContent = String(score);\n      tickIntervalMs = Math.max(MIN_INTERVAL_MS, tickIntervalMs - SPEEDUP_PER_FOOD_MS);\n      placeFood();\n    } else {\n      segments.pop();\n    }\n  }\n\n  function onGameOver() {\n    running = false;\n    best = Math.max(best, score);\n    bestEl.textContent = String(best);\n    setStatus(fill(STRINGS.gameOver, { score: score }), true);\n    post('over', { score: score, highScore: best });\n\n    if (resetTimer !== null) window.clearTimeout(resetTimer);\n    resetTimer = window.setTimeout(function () {\n      resetTimer = null;\n      resetGame();\n      running = true;\n    }, RESTART_DELAY_MS);\n  }\n\n  function setStatus(text, isResult) {\n    statusEl.textContent = text;\n    statusEl.classList.toggle('is-result', !!isResult);\n  }\n\n  /* ---- Rendering ----\n\n     Segment/food elements are absolutely positioned divs, pooled and reused\n     as the snake grows rather than rebuilt every frame. */\n\n  function ensurePool(count) {\n    while (segmentEls.length < count) {\n      var el = document.createElement('div');\n      el.className = 'segment';\n      boardEl.appendChild(el);\n      segmentEls.push(el);\n    }\n    while (segmentEls.length > count) {\n      var extra = segmentEls.pop();\n      boardEl.removeChild(extra);\n    }\n  }\n\n  function placeCell(el, col, row) {\n    var inset = cellSize > 10 ? 1 : 0;\n    el.style.left = (col * cellSize + inset) + 'px';\n    el.style.top = (row * cellSize + inset) + 'px';\n    el.style.width = (cellSize - inset * 2) + 'px';\n    el.style.height = (cellSize - inset * 2) + 'px';\n  }\n\n  function render() {\n    if (!cellSize) return;\n    ensurePool(segments.length);\n    for (var i = 0; i < segments.length; i++) {\n      var el = segmentEls[i];\n      el.className = 'segment' + (i === 0 ? ' head' : '');\n      // Body fades toward the tail so the direction of travel reads at a\n      // glance, same idea as the original.\n      el.style.opacity = i === 0 ? '1' : String(1 - (i / segments.length) * 0.55);\n      placeCell(el, segments[i].col, segments[i].row);\n    }\n    if (food) {\n      if (!foodEl) {\n        foodEl = document.createElement('div');\n        foodEl.className = 'segment food';\n        boardEl.appendChild(foodEl);\n      }\n      placeCell(foodEl, food.col, food.row);\n    }\n  }\n\n  /* ---- Game loop ----\n\n     A requestAnimationFrame loop that keeps running even across a death, so\n     the frozen board stays visible while the \"Game over\" line shows; only\n     the grid-step logic pauses on `running`. */\n\n  function loop(now) {\n    if (lastFrameTime === null) lastFrameTime = now;\n    var delta = now - lastFrameTime;\n    lastFrameTime = now;\n\n    if (running) {\n      tickAccumMs += delta;\n      // A while loop, not an if: a frame dropped by the host (tab hidden,\n      // WebView backgrounded) must not let the accumulator fire dozens of\n      // steps back-to-back when it returns.\n      var guard = 0;\n      while (tickAccumMs >= tickIntervalMs && guard < 5) {\n        tickAccumMs -= tickIntervalMs;\n        step();\n        guard += 1;\n        if (!running) break;\n      }\n      if (guard >= 5) tickAccumMs = 0;\n    }\n    render();\n    window.requestAnimationFrame(loop);\n  }\n\n  /* ---- Fitting the board to the frame ----\n\n     Same measuring technique as the tic-tac-toe bundle: the board is square\n     in logical cells, so its pixel size is derived from whichever of the\n     frame's width/height is tighter, and the chrome rows are measured rather\n     than assumed. */\n\n  var wrapEl = document.querySelector('.wrap');\n  var panelEl = document.querySelector('.panel');\n\n  function sizeBoard() {\n    var styles = window.getComputedStyle(wrapEl);\n    var gap = parseFloat(styles.rowGap) || 0;\n    var padding = parseFloat(styles.paddingTop) || 0;\n    var chrome = panelEl.offsetHeight + statusEl.offsetHeight + gap * 2 + padding * 2;\n    var byHeight = wrapEl.clientHeight - chrome;\n    var byWidth = wrapEl.clientWidth - padding * 2;\n    var available = Math.max(140, Math.floor(Math.min(byWidth, byHeight)) - 2);\n    cellSize = Math.max(4, Math.floor(available / COLS));\n    boardEl.style.width = (cellSize * COLS) + 'px';\n    boardEl.style.height = (cellSize * ROWS) + 'px';\n    var checker = cellSize * 2;\n    boardEl.style.backgroundImage =\n      'linear-gradient(45deg, var(--background-secondary) 25%, transparent 25%, transparent 75%, var(--background-secondary) 75%),' +\n      'linear-gradient(45deg, var(--background-secondary) 25%, transparent 25%, transparent 75%, var(--background-secondary) 75%)';\n    boardEl.style.backgroundSize = checker + 'px ' + checker + 'px';\n    boardEl.style.backgroundPosition = '0 0, ' + cellSize + 'px ' + cellSize + 'px';\n    render();\n  }\n\n  /** Sizing twice: the first pass changes the board's height, which decides\n   * whether the max-height chrome rules apply, which changes what the second\n   * pass measures — same reasoning as the tic-tac-toe bundle. */\n  function fit() {\n    sizeBoard();\n    window.requestAnimationFrame(sizeBoard);\n  }\n\n  /* ---- Controls ---- */\n\n  window.addEventListener('keydown', function (event) {\n    var code = event.keyCode || event.which;\n    var dir = null;\n    if (code === 38 || code === 87) dir = 'up';        // Up / W\n    else if (code === 40 || code === 83) dir = 'down';  // Down / S\n    else if (code === 37 || code === 65) dir = 'left';  // Left / A\n    else if (code === 39 || code === 68) dir = 'right'; // Right / D\n    if (!dir) return;\n    event.preventDefault();\n    requestDirection(dir);\n  });\n\n  // Touch swipe: the one control a keyboard-based host doesn't need but a\n  // WebView has no keyboard to offer instead.\n  var touchStartX = 0;\n  var touchStartY = 0;\n  boardEl.addEventListener('touchstart', function (event) {\n    var touch = event.touches[0];\n    touchStartX = touch.clientX;\n    touchStartY = touch.clientY;\n  }, { passive: true });\n\n  boardEl.addEventListener('touchend', function (event) {\n    var touch = event.changedTouches[0];\n    var dx = touch.clientX - touchStartX;\n    var dy = touch.clientY - touchStartY;\n    if (Math.max(Math.abs(dx), Math.abs(dy)) < SWIPE_MIN_PX) return;\n    if (Math.abs(dx) > Math.abs(dy)) {\n      requestDirection(dx > 0 ? 'right' : 'left');\n    } else {\n      requestDirection(dy > 0 ? 'down' : 'up');\n    }\n  }, { passive: true });\n\n  restartEl.innerHTML =\n    '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" ' +\n    'stroke-linecap=\"round\" stroke-linejoin=\"round\" focusable=\"false\" aria-hidden=\"true\">' +\n    '<path d=\"M3 12a9 9 0 1 0 3-6.7\"/><path d=\"M3 4v5h5\"/></svg>';\n  restartEl.addEventListener('click', function () {\n    if (resetTimer !== null) {\n      window.clearTimeout(resetTimer);\n      resetTimer = null;\n    }\n    resetGame();\n    running = true;\n  });\n\n  renderLabels();\n  resetGame();\n  fit();\n\n  // Both, deliberately. ResizeObserver catches a frame resized by its host\n  // without a window resize event (a drawer opening, an iframe re-laid out);\n  // the window events catch a rotation or a keyboard in a WebView, where the\n  // observer has been seen not to fire.\n  if (window.ResizeObserver) {\n    new ResizeObserver(fit).observe(document.documentElement);\n  }\n  window.addEventListener('resize', fit);\n  window.addEventListener('orientationchange', fit);\n\n  window.requestAnimationFrame(loop);\n  post('ready');\n})();\n</script>\n</body>\n</html>\n";
